package java_basics;

public class Comparison_operator {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		int a=76;
		int b=32;
		
		System.out.println(a==b);
		System.out.println(a!=b);
		System.out.println(a<b);
		System.out.println(a>b);
		System.out.println(a<=b);
		System.out.println(a>=b);
	}

}
